import { SetMetadata } from '@nestjs/common';
import { QUEUE_EVENTS_LISTENER_METADATA } from '../bull.constants.js';
/**
 * Represents a "QueueEvents" component (class that reacts to queue events).
 *
 * @publicApi
 */
export function QueueEventsListener(queueName, queueEventsOptions) {
    return (target) => {
        SetMetadata(QUEUE_EVENTS_LISTENER_METADATA, {
            queueName,
            queueEventsOptions,
        })(target);
    };
}
